language "moriarty-sherlock-draft/1";
program P {
  fn fold(t: Tree): UInt { match t { leaf(x) => x, branch(l, r) => fold(l) + fold(r) } }
  entry fold(branch(leaf(4), leaf(4)));
}

language "moriarty-sherlock-draft/1";
program P {
  fn fold(t: Tree): UInt { match t { leaf(x) => x, branch(l, r) => fold(l) + fold(r) } }
  entry (let s = leaf(4) in fold(branch(s, s)));
}

language "moriarty-sherlock-draft/1";
program P {
  fn fold(t: Tree): UInt { match t { leaf(x) => x, branch(l, r) => fold(l) + fold(r) } }
  entry fold(branch(branch(leaf(1), leaf(2)), branch(leaf(1), leaf(2))));
}

language "moriarty-sherlock-draft/1";
program P {
  fn fold(t: Tree): UInt { match t { leaf(x) => x, branch(l, r) => fold(l) + fold(r) } }
  entry fold(branch(leaf(4), leaf(5)));
}

language "moriarty-sherlock-draft/1";
program P {
  fn fact(n: UInt): UInt { if n == 0 { 1 } else { n * fact(n - 1) } }
  entry fact(3);
}
